from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PmtuDiscoveryResult(SchemaObject):
    path_mtu = SchemaField(name='pathMTU', not_null=True)
    local_mtu = SchemaField(name='localMTU', not_null=True)

    def __init__(self, path_mtu, local_mtu):
        self.path_mtu = path_mtu
        self.local_mtu = local_mtu

        super(PmtuDiscoveryResult, self).__init__()


class GetPmtuDiscoveryStatus(SchemaObject):
    status = SchemaField(name='status', not_null=True)
    result = SchemaField(name='result', optional=True, klass=PmtuDiscoveryResult)
    reason = SchemaField(name='reason', optional=True)

    def __init__(self, status, result, reason):
        self.status = status
        self.result = result
        self.reason = reason

        super(GetPmtuDiscoveryStatus, self).__init__()
